function compute(x){
  const Q = x.Q, K = x.K, V = x.V;
  const n = Q.length, dk = Q[0].length, m = K.length, dv = V[0].length;
  // scores S = Q K^T
  const S = [];
  for(let i=0;i<n;i++){
    S.push([]);
    for(let j=0;j<m;j++){
      let s=0;
      for(let t=0;t<dk;t++) s += Q[i][t]*K[j][t];
      S[i].push(s);
    }
  }
  const denom = x.scale ? Math.sqrt(dk) : 1;
  const Sscaled = S.map(row => row.map(v => v/denom));
  // softmax each row
  const A = Sscaled.map(row => {
    const mx = Math.max(...row);
    const ex = row.map(v => Math.exp(v-mx));
    const sum = ex.reduce((a,b)=>a+b,0);
    return ex.map(v => v/sum);
  });
  // output O = A V
  const O = [];
  for(let i=0;i<n;i++){
    O.push([]);
    for(let j=0;j<dv;j++){
      let s=0;
      for(let t=0;t<m;t++) s += A[i][t]*V[t][j];
      O[i].push(s);
    }
  }
  const rowSums = A.map(r => r.reduce((a,b)=>a+b,0));
  const maxRowSumErr = Math.max(...rowSums.map(s => Math.abs(s-1)));
  const insight = `Each row of A sums to 1 (max error ${maxRowSumErr.toExponential(2)}). Output O is the weighted sum of V rows.`;
  return {
    S: {type:'matrix', value:S, rowLabels:Q.map((_,i)=>'q'+i), colLabels:K.map((_,j)=>'k'+j), label:'Raw scores S = Q K^T'},
    Sscaled: {type:'matrix', value:Sscaled, rowLabels:Q.map((_,i)=>'q'+i), colLabels:K.map((_,j)=>'k'+j), label:'Scaled scores'},
    A: {type:'matrix', value:A, rowLabels:Q.map((_,i)=>'q'+i), colLabels:K.map((_,j)=>'k'+j), label:'Attention weights A'},
    O: {type:'matrix', value:O, rowLabels:Q.map((_,i)=>'q'+i), colLabels:V[0].map((_,j)=>'v'+j), label:'Output O = A V'},
    rowSums: {type:'vector', value:rowSums, labels:Q.map((_,i)=>'q'+i), label:'Row sums of A'},
    insight: {type:'scalar', value:maxRowSumErr, label:'Max |row sum - 1|'}
  };
}
